const drums = s("bd*4, ~ sd ~ sd, hh*8").bank("RolandTR909")
const bass = note("<a3 f3 c3 g3>").ply(8).s("sawtooth").lpf(700).gain(0.6)
const pad = (chords) =>
  chord(chords).voicing().s("supersaw").detune(0.2).lpf(2000).gain(0.35)
const pedal = note("e3")
  .ply(8)
  .s("sawtooth")
  .lpf(saw.slow(4).rangex(300, 3000))
  .gain(0.6)
const riser = s("white*16")
  .decay(0.1)
  .sustain(0)
  .lpf(saw.slow(4).rangex(400, 8000))
  .gain(saw.slow(4).rangex(0.05, 0.4))
const verse = stack(drums, bass)
const chorus = stack(drums, bass, pad("<Am F C G>"))
const breakdown = stack(pedal, pad("<F Dm Am E>"), riser)
