$: note("<e3 c3 g3 d3>")
  .ply(8)
  .s("sawtooth")
  .lpf(600)
  .gain(0.6)
  .mask("<0 0 0 0 1 1 1 1>")
$: chord("<Em C G D>")
  .voicing()
