const bass = note("<c3 ab3 eb3 bb3>").s("sawtooth").lpf(600).gain(0.6)
const pad = chord("<Cm Ab Eb Bb>").voicing().s("triangle").gain(0.45)
const bell = n("4 ~ 2 ~ 0 ~ 2 ~")
  .scale("C5:minor")
  .s("sine")
  .decay(0.4)
  .sustain(0)
  .gain(0.4)
const fill = (x) => x.rev()

const intro = pad
const verse = stack(s("bd ~ sd ~").bank("RolandTR808"), bass.ply(4), pad)
const chorus = stack(
  s("bd*4, ~ cp ~ cp, hh*8").bank("RolandTR808"),
  bass.ply(8),
  pad,
  bell.lastOf(4, fill),
)

